package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.BackchannelLogoutSessionRequiredVO;

class BackchannelLogoutSessionRequiredValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of backchannel logout session required of oauth client")
  void test_backchannel_logout_session_required_value_holder_assign_plain_value() {
    Object holder = new Object();
    BackchannelLogoutSessionRequiredValueHolder<Object> value =
        new BackchannelLogoutSessionRequiredValueHolder<>(holder);
    Assertions.assertSame(holder, value.backchannelLogoutSessionRequired(true),
        "Setters must return the holder");
    Assertions.assertTrue(value.getBackchannelLogoutSessionRequiredValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getBackchannelLogoutSessionRequired().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.backchannelLogoutSessionRequiredNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getBackchannelLogoutSessionRequiredValue().isPresent(),
        "A null value object must be stored");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of backchannel logout session required of oauth client")
  void test_backchannel_logout_session_required_value_holder_assign_value_object() {
    Object holder = new Object();
    BackchannelLogoutSessionRequiredValueHolder<Object> value =
        new BackchannelLogoutSessionRequiredValueHolder<>(holder);
    BackchannelLogoutSessionRequiredVO vo = BackchannelLogoutSessionRequiredVO.from(true);
    Assertions.assertFalse(value.getBackchannelLogoutSessionRequiredValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.backchannelLogoutSessionRequired(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getBackchannelLogoutSessionRequiredValue().orElseThrow());
    Assertions.assertSame(holder, value.backchannelLogoutSessionRequired(Optional.empty()));
    Assertions.assertFalse(value.getBackchannelLogoutSessionRequiredValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.backchannelLogoutSessionRequired(Optional.of(vo)));
    Assertions.assertSame(vo, value.getBackchannelLogoutSessionRequiredValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of backchannel logout session required of oauth client against the original")
  void test_backchannel_logout_session_required_value_holder_read() {
    Object holder = new Object();
    BackchannelLogoutSessionRequiredValueHolder<Object> value =
        new BackchannelLogoutSessionRequiredValueHolder<>(holder);
    BackchannelLogoutSessionRequiredVO vo = BackchannelLogoutSessionRequiredVO.from(true);
    BackchannelLogoutSessionRequiredVO other = BackchannelLogoutSessionRequiredVO.from(true);
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getBackchannelLogoutSessionRequiredValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other,
        value.readBackchannelLogoutSessionRequired(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readBackchannelLogoutSessionRequired(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.backchannelLogoutSessionRequired(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo,
        value.readBackchannelLogoutSessionRequired(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readBackchannelLogoutSessionRequired(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of backchannel logout session required of oauth client")
  void test_backchannel_logout_session_required_value_holder_unset() {
    Object holder = new Object();
    BackchannelLogoutSessionRequiredValueHolder<Object> value =
        new BackchannelLogoutSessionRequiredValueHolder<>(holder);
    BackchannelLogoutSessionRequiredVO vo = BackchannelLogoutSessionRequiredVO.from(true);
    value.backchannelLogoutSessionRequired(vo);
    Assertions.assertSame(holder, value
        .unsetBackchannelLogoutSessionRequiredIfMatches("backchannelLogoutSessionRequired_other"));
    Assertions.assertTrue(value.getBackchannelLogoutSessionRequiredValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetBackchannelLogoutSessionRequiredIfMatches("backchannelLogoutSessionRequired"));
    Assertions.assertFalse(value.getBackchannelLogoutSessionRequiredValue().isPresent(),
        "The field name must clear the value");
    value.backchannelLogoutSessionRequired(vo);
    Assertions.assertSame(holder, value.unsetBackchannelLogoutSessionRequired());
    Assertions.assertFalse(value.getBackchannelLogoutSessionRequiredValue().isPresent(),
        "Unset must clear the value");
  }
}
